// HasPlaybook applies the HasEdge predicate on the "playbook" edge.
func HasPlaybook() predicate.CollectionPlaybookRun {
	return predicate.CollectionPlaybookRun(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, PlaybookTable, PlaybookColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPlaybookWith applies the HasEdge predicate on the "playbook" edge with a given conditions (other predicates).
func HasPlaybookWith(preds ...predicate.CollectionPlaybook) predicate.CollectionPlaybookRun {
	return predicate.CollectionPlaybookRun(func(s *sql.Selector) {
		step := newPlaybookStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasStepRuns applies the HasEdge predicate on the "step_runs" edge.
func HasStepRuns() predicate.CollectionPlaybookRun {
	return predicate.CollectionPlaybookRun(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, StepRunsTable, StepRunsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasStepRunsWith applies the HasEdge predicate on the "step_runs" edge with a given conditions (other predicates).
func HasStepRunsWith(preds ...predicate.CollectionPlaybookStepRun) predicate.CollectionPlaybookRun {
	return predicate.CollectionPlaybookRun(func(s *sql.Selector) {
		step := newStepRunsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CollectionPlaybookRun) predicate.CollectionPlaybookRun {
	return predicate.CollectionPlaybookRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CollectionPlaybookRun) predicate.CollectionPlaybookRun {
	return predicate.CollectionPlaybookRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CollectionPlaybookRun) predicate.CollectionPlaybookRun {
	return predicate.CollectionPlaybookRun(sql.NotPredicates(p))
}
